                E_('first_fruits_declaration_commanded', I, value={'the_word': "and say to him: I declare this day to the LORD your God (26:3)", 'the_status': "once a year; the window Shavuot to the Feast A CLOCK DATUM; the convert and the guardian bring without reciting — parameters (Bikkurim 1:4-6, 1:8, 1:10)", 'the_day': D_}, law="F1 [INK 26:3 — compiled at 18b; the Sifrei 299]"),
